const chains={op:{name:'OP Mainnet',id:10,block:130482901},base:{name:'Base',id:8453,block:35482901},uni:{name:'Unichain',id:130,block:28482901}};
let selected='op',stage=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches;
const descriptions=[()=>`Connect to ${chains[selected].name} peers. Receive sequencer-signed blocks directly from the gossip network.`,()=>`Validate sequencer signatures and receipt roots. With L1 tracking enabled, follow safe and finalized heads.`,()=>`Promote committed blocks into the local archive. Fleet exporters seal finalized history into immutable chunks.`,()=>`Serve history, then live data over gRPC. Read columnar blocks, transactions, receipts and logs with Arrow Flight.`];
function render(){document.querySelector('#stage-description').textContent=descriptions[stage]();document.querySelector('#chain-id b').textContent=chains[selected].id;document.querySelector('#block-number').textContent=chains[selected].block.toLocaleString('en-US');document.querySelectorAll('.chain').forEach(b=>{const active=b.dataset.chain===selected;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});document.querySelectorAll('.stage').forEach(b=>{const active=Number(b.dataset.stage)===stage;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)})}
document.querySelectorAll('.chain').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.chain;render()}));document.querySelectorAll('.stage').forEach(b=>b.addEventListener('click',()=>{stage=Number(b.dataset.stage);render()}));
function setPaused(){const svg=document.querySelector('.wires');paused?svg.pauseAnimations():svg.unpauseAnimations();document.querySelector('#pause').textContent=paused?'▷ Play':'Ⅱ Pause';document.querySelector('#pause').setAttribute('aria-label',paused?'Play simulation':'Pause simulation')}
document.querySelector('#pause').addEventListener('click',()=>{paused=!paused;setPaused()});setPaused();setInterval(()=>{if(!paused){chains[selected].block++;render()}},2000);
const code={grpc:{comment:'// One subscription. History → live.',text:'opindexer.v1.Stream\n\nSubscribe   history + live blocks\nGetHeads    unsafe / safe / finalized\nGetBlock    look up a single block',footer:'Reorg events · Finality markers · Late receipts'},arrow:{comment:'// Example DoGet ticket · finalized logs',text:'logs:120000000:120010000:finalized\n\n→ Apache Arrow record batches\n→ blocks · transactions · receipts · logs\n→ DuckDB · Polars · Spark',footer:'Columnar data · Up to 100,000 blocks per ticket'}};
function showCode(key){document.querySelector('#code-comment').textContent=code[key].comment;document.querySelector('#code-sample').textContent=code[key].text;document.querySelector('#code-footer').textContent=code[key].footer;document.querySelectorAll('[data-code]').forEach(b=>{b.classList.toggle('active',b.dataset.code===key);b.setAttribute('aria-pressed',b.dataset.code===key)})}document.querySelectorAll('[data-code]').forEach(b=>b.addEventListener('click',()=>showCode(b.dataset.code)));showCode('grpc');
document.querySelector('#copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.querySelector('#install-code').textContent);document.querySelector('#copy-status').textContent='Install command copied.';document.querySelector('#copy').textContent='Copied';}catch{document.querySelector('#copy-status').textContent='Select the command above to copy it.'}});render();
